        blob = vips_blob_new( NULL, buf, len );

        va_start( ap, option_string );
        result = vips_call_split_option_string( operation_name,
                option_string, ap, blob, &out );
        va_end( ap );

        vips_area_unref( VIPS_AREA( blob ) );

        if( result )
                return( NULL );

        return( out );
}

